    for i in range(n):
        row = []
        for j in range(m):
            size = min(n - i, m - j)
            for k in range(1, size + 1):
                if (i + k <= n) and (j + k <= m):
                    size = k
            for x in range(size):
                for y in range(size):
                    row.append(current_char)
            j += size - 1
            current_char = chr(ord(current_char) + 1)
            if current_char > 'Z':
                current_char = 'A'
        result.append(''.join(row))
    print('\n'.join(result))

